import React, { Fragment, useState } from 'react';
import type { FC } from 'react';
import { join, dirname, relative, basename } from 'node:path';
import { readdir } from 'node:fs/promises';
import { match } from 'variant';
import { useAsync, Spinner, Alert, Text, Box } from '@wix/cli-ui-kit';
import { outputFile } from '@wix/cli-fs';
import { CliError, CliErrorCode } from '@wix/cli-error';
import type { SupportedExtensionTopologyItem } from '@wix/cli-astro-definitions';
import kebabCase from 'lodash/kebabCase.js';
import { extractComponentManifest } from '@wix/zero-config-implementation';
import type { ExtractionError } from '@wix/zero-config-implementation';
import { useProjectModel } from '../../model.js';
import { assertBuildOutputExists } from '../../files/assert-build-output-exists.js';
import { readBuildMetadata } from '../../files/build-metadata.js';

type EditorReactExtension = Extract<
  SupportedExtensionTopologyItem,
  { type: 'EDITOR_REACT_COMPONENT' }
>;

type TaskStatus =
  | { status: 'running'; componentId: string }
  | { status: 'success'; relativePath: string }
  | { status: 'warning'; relativePath: string; errors: ExtractionError[] };

type CompletedTask = Extract<TaskStatus, { status: 'success' | 'warning' }>;

async function generateManifestForExtension(
  ext: EditorReactExtension,
  projectFolder: string
): Promise<{ relativePath: string; errors: ExtractionError[] }> {
  try {
    const { srcPath, distPath } = ext.topology['resources.client.componentUrl'];
    const folder = dirname(srcPath);
    const extensionFiles = (await readdir(folder)).filter((file) =>
      file.endsWith('.extension.ts')
    );
    if (extensionFiles.length > 1) {
      throw new CliError({
        code: CliErrorCode.MultipleExtensionFilesInOneFolder({ folder }),
        cause: undefined,
      });
    }

    const extensionFile = extensionFiles[0];
    const fileName = extensionFile
      ? basename(extensionFile, '.extension.ts')
      : kebabCase(basename(folder));
    const filePath = join(folder, `${fileName}.generated.ts`);

    const res = await extractComponentManifest(srcPath, distPath);
    const content = [
      `/**`,
      ` * THIS FILE IS AUTO-GENERATED — DO NOT EDIT.`,
      ` * It contains the \`editorElement\` portion of the manifest, automatically derived from your component's`,
      ` * source code, prop types, and CSS rules.`,
      ` * Update your source code and run \`npx wix build && npx wix generate manifest\` to regenerate it.`,
      ` * If you need to override specific manifest values (sizing, layout, etc.),`,
      ` * you can do so in ${fileName}.extension.ts.`,
      ` */`,
      ``,
      `import type { EditorElement } from '@wix/react-component-schema';`,
      ``,
      `export const editorElement = ${JSON.stringify(res.component.editorElement, null, 2)} as EditorElement;`,
      ``,
    ].join('\n');

    await outputFile(filePath, content);

    return {
      relativePath: relative(projectFolder, filePath),
      errors: res.errors,
    };
  } catch (cause) {
    throw new CliError({
      code: CliErrorCode.FailedToGenerateExtensionConfig({
        extensionId: ext.id,
      }),
      cause,
    });
  }
}

function formatExtractionError(err: ExtractionError): string {
  return `[${err.phase}] ${err.componentName}: ${err.error.message}`;
}

const ManifestTaskList: FC<{
  extensions: EditorReactExtension[];
  projectFolder: string;
}> = ({ extensions, projectFolder }) => {
  const total = extensions.length;
  const [tasks, setTasks] = useState<TaskStatus[]>([]);

  useAsync(async () => {
    const completed: CompletedTask[] = [];
    for (const ext of extensions) {
      setTasks([...completed, { status: 'running', componentId: ext.id }]);
      const { relativePath, errors } = await generateManifestForExtension(
        ext,
        projectFolder
      );
      completed.push(
        errors.length === 0
          ? { status: 'success', relativePath }
          : { status: 'warning', relativePath, errors }
      );
    }
    setTasks(completed);
  }, []);

  return (
    <>
      {tasks.map((task, i) => {
        const stepper = `[${i + 1}/${total}]`;
        switch (task.status) {
          case 'running':
            return (
              <Spinner
                key={i}
                text={`${stepper} Generating config for component ${task.componentId}`}
              />
            );
          case 'success':
            return (
              <Alert key={i} type="success">
                {`${stepper} Generated ${task.relativePath}`}
              </Alert>
            );
          case 'warning':
            return (
              <Fragment key={i}>
                <Alert type="warning">
                  {`${stepper} Generated ${task.relativePath}`}
                </Alert>
                {task.errors.map((err, j) => (
                  <Box
                    key={j}
                    paddingLeft={2}
                    paddingBottom={1}
                    flexDirection="column"
                  >
                    <Alert type="insight">{formatExtractionError(err)}</Alert>
                  </Box>
                ))}
              </Fragment>
            );
        }
      })}
    </>
  );
};

export const GenerateManifestCommand: FC = () => {
  const { model } = useProjectModel();

  const { status } = useAsync(async () => {
    await assertBuildOutputExists(model.projectFolder, model.config);
    return readBuildMetadata(model.projectFolder, model.config);
  }, []);

  return match(status, {
    Error: () => null,
    Loading: () => null,
    Success: ({ result }) => {
      const extensions = (result.extensionsTopology ?? []).filter(
        (ext): ext is EditorReactExtension =>
          ext.type === 'EDITOR_REACT_COMPONENT'
      );
      if (extensions.length === 0) {
        return <Text>No extensions that can generate manifest for exist</Text>;
      }

      return (
        <ManifestTaskList
          extensions={extensions}
          projectFolder={model.projectFolder}
        />
      );
    },
  });
};
